// Service Worker — auto-generated by PWA 打包神器
// Strategy: Network-First (HTML，離線時用快取/離線頁) + Cache-First (assets)
// 更新 index.html 後請把 CACHE_NAME 的版本號 +1

const CACHE_NAME = 'ai秘境塔羅-v8';
const PRECACHE_URLS = [
    "/tarot/index.html",
    "/tarot/sw.js",
    "/tarot/manifest.json",
    "/tarot/icon.svg",
    "/tarot/offline.html",
    "/tarot/icon-192.png",
    "/tarot/icon-512.png",
    "/tarot/icon-maskable.svg",
    "/tarot/apple-touch-icon.png"
];

// Install: pre-cache assets
self.addEventListener('install', event => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(cache => {
      return cache.addAll(PRECACHE_URLS).catch(err => {
        console.warn('[SW] Pre-cache partial failure:', err);
      });
    }).then(() => self.skipWaiting())
  );
});

// Activate: clean old caches
self.addEventListener('activate', event => {
  event.waitUntil(
    caches.keys().then(keys =>
      Promise.all(
        keys.filter(k => k !== CACHE_NAME)
            .map(k => caches.delete(k))
      )
    ).then(() => self.clients.claim())
  );
});

// Fetch strategy:
//   HTML documents → Stale-While-Revalidate（先給舊的，背景更新）
//   其他資源      → Cache-First（快取優先，離線可用）
self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (url.protocol === 'chrome-extension:') return;

  const isDocument = event.request.destination === 'document' ||
                     event.request.headers.get('accept')?.includes('text/html');

  if (isDocument) {
    // Network-First for HTML：有網路就拿最新版並更新快取；
    // 離線才用快取，連快取都沒有時顯示離線頁
    event.respondWith(
      fetch(event.request).then(response => {
        if (response && response.status === 200) {
          const copy = response.clone();
          caches.open(CACHE_NAME).then(cache => cache.put(event.request, copy));
        }
        return response;
      }).catch(async () => {
        const cached = await caches.match(event.request, { ignoreSearch: true })
                    || await caches.match('/tarot/index.html');
        return cached || caches.match('/tarot/offline.html');
      })
    );
  } else {
    // Cache-First for assets
    event.respondWith(
      caches.match(event.request).then(cached => {
        if (cached) return cached;
        return fetch(event.request).then(response => {
          if (!response || response.status !== 200 || response.type === 'opaque') {
            return response;
          }
          const cloned = response.clone();
          caches.open(CACHE_NAME).then(cache => cache.put(event.request, cloned));
          return response;
        }).catch(() => {
          if (event.request.destination === 'document') {
            return caches.match('/tarot/offline.html');
          }
        });
      })
    );
  }
});

// 點擊每日提醒通知 → 開啟（或聚焦）App
self.addEventListener('notificationclick', event => {
  event.notification.close();
  event.waitUntil(
    self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(list => {
      for (const c of list) {
        if (c.url.includes('/tarot/') && 'focus' in c) return c.focus();
      }
      return self.clients.openWindow('/tarot/');
    })
  );
});
